/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: LookupApplicationIntent
 *   Functions: isLookupValuePath, lookupCandidateValues, sameLookupValue, applyLookupCandidate,
 *              applyPreselectedLookup, rerankStoredLookup, lookupAnswersNeeded, chooseLookupCandidate,
 *              resolveLookupConflicts
 * Internal
 *   Types: TextResult
 *   Functions: stale, emptyValue, emptyFor, slotOf, isRecord, valueAt, applicable, lookupText,
 *              lookupArtistEntries, isEntryLike, storedValues, storedConflicts, rerankEvidence
 *   Constants: lookupPath, invisible
 * @end-catalog */

/**
 * Metadata lookup value application (pure: it changes the given import document and lookup record in memory only; callers persist
 * them in one transaction). A candidate's supported values reach the draft only through applyAutomaticValues, so they fill empty or
 * automatic values; a value that differs from the administrator's own becomes an unanswered conflict instead, and nothing is
 * preselected. Applying another candidate, or none, replaces the values the earlier application wrote that are still automatic
 * and still as written, falling back to file-tag values or empty. Owner rules: the confirmed Administrator Metadata Lookup rules
 * (they land with the summary).
 */
import { normalizeJoinPhrase } from '../../models/catalogCredit';
import { AdminImportError, invalidImport, parseImportDate } from '../import/adminImportContract';
import { importTagValues } from '../import/adminImportAutomation';
import {
    DRAFT_V2_LIMITS, derivedEntryKey, foldImportName, originKey, retainBoundDecisions, sameDraftValue, type ImportArtistEntry, type ImportDraftV2
} from '../import/adminImportDraft';
import type { AdminImportDocument } from '../import/adminImportService';
import {
    applyAutomaticValues, draftValueAt, draftWithinSizeLimit, markAdministratorValues, originOf, parseDraftValue, setDraftValue, storedDraftV2,
    type ImportAutomaticValue, type ImportDraftPath
} from '../import/adminImportValueState';
import type { MusicBrainzRelease } from './lookupContract';
import { normalizeMusicBrainzId } from './lookupIdentifiers';
import { lookupTrackAssignment, proposalForRelease, type LocalFileEvidence } from './lookupRanking';
import {
    importLookupFileSet, isBlockingLookupState, lookupFileEvidence, rankLookupWithinBudget, refreshLookupGrant, type LookupApplication, type LookupAppliedValue,
    type LookupConflict, type LookupValueFlag, type MetadataLookupRecord, type StoredLookupCandidate
} from './metadataLookupRecord';

/** The value paths lookup supplies: never visibility. */
const lookupPath = /^(?:album\.(?:title|artists|label|releaseDate)|tracks\.[^.]+\.(?:title|discNumber|trackNumber))$/;
export const isLookupValuePath = (path: unknown): path is ImportDraftPath => typeof path === 'string' && path.length <= 80 && lookupPath.test(path);
const invisible = /[\p{Cc}\p{Cf}\p{Cs}]/u;
const stale = () => new AdminImportError(409, 'ADMIN_IMPORT_LOOKUP_STALE');
const emptyValue = (value: unknown) => value === '' || value === null || (Array.isArray(value) && value.length === 0);
/** The empty value of a path, which an application that reverts a value without a file-tag value writes. */
const emptyFor = (path: ImportDraftPath): unknown => path === 'album.artists' ? [] : path === 'album.title' || path.endsWith('.title') ? '' : null;
const slotOf = (path: ImportDraftPath) => path.startsWith('tracks.') ? path.split('.')[1] : null;
const isRecord = (value: unknown): value is Record<string, unknown> => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
/** The current value at a path, or null when the stored draft lacks it (a malformed path is skipped, never written). */
const valueAt = (draft: ImportDraftV2, path: ImportDraftPath): { value: unknown } | null => { try { return { value: draftValueAt(draft, path) }; } catch { return null; } };
/**
 * Whether a candidate's details are complete enough to apply: fetched, and for the release the candidate names (a release that
 * MusicBrainz answered under another ID, such as a merged one, ranks as incomplete and is never applied).
 */
const applicable = (candidate: StoredLookupCandidate): boolean => candidate.details === 'fetched' && Boolean(candidate.release)
    && normalizeMusicBrainzId(candidate.release!.releaseId) !== null && normalizeMusicBrainzId(candidate.release!.releaseId) === normalizeMusicBrainzId(candidate.releaseId);

type TextResult = { text: string } | { reason: 'characters' | 'length' } | null;
/** Automatic text: NFC and trimmed; empty is no value; control, invisible formatting or lone surrogate characters, or over `max`, is left out and flagged. */
function lookupText(raw: unknown, max: number): TextResult {
    if (typeof raw !== 'string') return null;
    const text = raw.normalize('NFC').trim();
    if (!text) return null;
    if (invisible.test(text)) return { reason: 'characters' };
    return text.length > max ? { reason: 'length' } : { text };
}

/**
 * The candidate's Artist entries in credit order with their roles and join phrases, or the reason the whole value is left out:
 * one entry whose name has control or invisible characters or is over 200, an invalid or over-16 join phrase, more than 20
 * entries, or only placeholder credits. Nothing is stripped or truncated. An entry keeps the key of the current entry with the
 * same folded name, else a key derived from its folded name, so decisions on unchanged entries are kept. IDs wait for S13.
 */
function lookupArtistEntries(release: MusicBrainzRelease, draft: ImportDraftV2, importId: string): { entries: ImportArtistEntry[] } | { reason: LookupValueFlag['reason'] } | null {
    const proposed = proposalForRelease(release).artists;
    if (!proposed.length) return release.artistCredit.length ? { reason: 'placeholder' } : null;
    if (proposed.length > DRAFT_V2_LIMITS.artists) return { reason: 'length' };
    const parsed: Omit<ImportArtistEntry, 'key' | 'musicBrainzId'>[] = [];
    for (const entry of proposed) {
        const name = lookupText(entry.name, DRAFT_V2_LIMITS.name);
        if (!name) return { reason: 'format' };
        if ('reason' in name) return { reason: name.reason };
        let joinPhrase: string | null = null;
        if (entry.joinPhrase !== null) { try { joinPhrase = normalizeJoinPhrase(entry.joinPhrase) ?? null; } catch { return { reason: 'format' }; } }
        parsed.push({ name: name.text, role: entry.role, joinPhrase });
    }
    const current = new Map((Array.isArray(draft.album.artists) ? draft.album.artists : []).map(entry => [foldImportName(entry.name), entry.key]));
    const taken = new Set<string>();
    const reused = parsed.map(entry => { const key = current.get(foldImportName(entry.name)); if (!key || taken.has(key)) return null; taken.add(key); return key; });
    return { entries: parsed.map((entry, index) => {
        let key = reused[index];
        for (let attempt = 0; !key; attempt++) {
            const seed = { importId, lookupEntry: foldImportName(entry.name), ...(attempt ? { attempt } : {}) }, derived = derivedEntryKey(seed);
            if (!taken.has(derived)) { taken.add(derived); key = derived; }
        }
        return { key, name: entry.name, role: entry.role, joinPhrase: entry.joinPhrase, musicBrainzId: null };
    }) };
}

/**
 * Every supported value of a fetched release, in the order album title, Artist entries, label, date, then each matched file's
 * title, Disc Number and Track Number (only when the candidate's track count equals the file count, in the ranking's file order),
 * and the values left out with their reason. A `[no label]` label and placeholder credits are never values; only a release that
 * credits nothing but placeholders is flagged. Pure.
 */
export function lookupCandidateValues(release: MusicBrainzRelease, files: readonly LocalFileEvidence[], draft: ImportDraftV2, importId: string):
    { values: LookupAppliedValue[]; flagged: LookupValueFlag[] } {
    const values: LookupAppliedValue[] = [], flagged: LookupValueFlag[] = [];
    const text = (path: ImportDraftPath, raw: unknown, max: number) => {
        const result = lookupText(raw, max);
        if (result && 'reason' in result) flagged.push({ path, reason: result.reason });
        else if (result) values.push({ path, value: result.text, slotId: slotOf(path) });
    };
    const proposal = proposalForRelease(release);
    text('album.title', proposal.albumTitle, DRAFT_V2_LIMITS.title);
    const artists = lookupArtistEntries(release, draft, importId);
    if (artists && 'reason' in artists) flagged.push({ path: 'album.artists', reason: artists.reason });
    else if (artists) values.push({ path: 'album.artists', value: artists.entries, slotId: null });
    if (proposal.label !== null) {
        const label = lookupText(proposal.label, DRAFT_V2_LIMITS.name);
        if (label && 'reason' in label) flagged.push({ path: 'album.label', reason: label.reason });
        else if (label) values.push({ path: 'album.label', value: { name: label.text, musicBrainzId: null }, slotId: null });
    }
    // The release group's first-release date at its precision, else the release's own (proposalForRelease chooses).
    if (proposal.releaseDate) {
        try { values.push({ path: 'album.releaseDate', value: parseImportDate({ year: proposal.releaseDate.year, month: proposal.releaseDate.month, day: proposal.releaseDate.day }), slotId: null }); }
        catch { flagged.push({ path: 'album.releaseDate', reason: 'format' }); }
    }
    const slots = new Set((Array.isArray(draft.tracks) ? draft.tracks : []).map(track => track?.slotId));
    for (const track of lookupTrackAssignment(release, files) ?? []) {
        if (!slots.has(track.slotId)) continue;
        text(`tracks.${track.slotId}.title`, track.title, DRAFT_V2_LIMITS.title);
        const number = (path: ImportDraftPath, value: number, max: number) => {
            if (Number.isInteger(value) && value >= 1 && value <= max) values.push({ path, value, slotId: track.slotId });
            else flagged.push({ path, reason: 'format' });
        };
        number(`tracks.${track.slotId}.discNumber`, track.discNumber, DRAFT_V2_LIMITS.disc);
        number(`tracks.${track.slotId}.trackNumber`, track.trackNumber, DRAFT_V2_LIMITS.track);
    }
    return { values, flagged };
}

const isEntryLike = (value: unknown): value is { name: string; role: unknown; joinPhrase?: unknown } => isRecord(value) && typeof value.name === 'string';
/**
 * Whether the current value already says what lookup would write: Artist entries by count, then per position the folded name, role
 * and join phrase; the label by folded name; anything else exactly. MusicBrainz IDs never count here.
 */
export function sameLookupValue(path: string, current: unknown, value: unknown): boolean {
    if (path === 'album.artists') {
        if (!Array.isArray(current) || !Array.isArray(value) || current.length !== value.length) return false;
        return current.every((entry, index) => {
            const other = value[index];
            return isEntryLike(entry) && isEntryLike(other) && foldImportName(entry.name) === foldImportName(other.name) && entry.role === other.role
                && (entry.joinPhrase ?? null) === (other.joinPhrase ?? null);
        });
    }
    if (path === 'album.label') {
        if (current === null || value === null) return current === value;
        return isEntryLike(current) && isEntryLike(value) && foldImportName(current.name) === foldImportName(value.name);
    }
    return sameDraftValue(current, value);
}

const storedValues = (application: LookupApplication | null | undefined): LookupAppliedValue[] =>
    Array.isArray(application?.values) ? application!.values.filter(item => isRecord(item) && isLookupValuePath(item.path)) : [];
const storedConflicts = (application: LookupApplication | null | undefined): LookupConflict[] =>
    Array.isArray(application?.conflicts) ? application!.conflicts.filter(item => isRecord(item) && isLookupValuePath(item.path)) : [];

export type LookupApplicationIntent = {
    run: number; choice: LookupApplication['choice']; basis: LookupApplication['basis']; actorId: string; operationId: string | null; now: Date;
};
/**
 * Applies a fetched candidate, or none, to `doc` in memory, all or nothing for the document (its caller writes it, the record
 * and the gate in one transaction). Every supplied value targets its path; every value the previous application wrote that is
 * still automatic and unchanged, and that this candidate does not supply, returns to its file-tag value or empty (an emptied
 * value loses its origin). A supplied value that differs from a non-empty administrator value is a conflict (an earlier answer
 * to the same lookup value is kept) and is not written. Writes bump `valueRevision` and keep only decisions still bound to their
 * entry or label; `revision` and receipts never change. Applying the same candidate again writes nothing.
 */
export function applyLookupCandidate(doc: AdminImportDocument, previous: LookupApplication | null | undefined, candidate: StoredLookupCandidate | null,
    intent: LookupApplicationIntent): { application: LookupApplication; changed: boolean } {
    const draft = storedDraftV2(doc), origins = doc.draftOrigins ??= {};
    const supplied = candidate?.release ? lookupCandidateValues(candidate.release, lookupFileEvidence(doc), draft, doc._id.toHexString()) : { values: [], flagged: [] };
    const suppliedPaths = new Set<string>(supplied.values.map(item => item.path));
    const targets: { path: ImportDraftPath; value: unknown; slotId: string | null; supplied: boolean }[] = supplied.values.map(item => ({ ...item, supplied: true }));
    let tagValues: Map<ImportDraftPath, unknown> | undefined;
    for (const item of storedValues(previous)) {
        if (suppliedPaths.has(item.path) || originOf(origins, item.path) !== 'automatic') continue;
        const current = valueAt(draft, item.path);
        if (!current || !sameDraftValue(current.value, item.value)) continue;
        tagValues ??= importTagValues(doc);
        targets.push({ path: item.path, value: tagValues.has(item.path) ? tagValues.get(item.path) : emptyFor(item.path), slotId: slotOf(item.path), supplied: false });
    }
    const answered = storedConflicts(previous).filter(item => item.answer === 'mine' || item.answer === 'lookup');
    const conflicts: LookupConflict[] = [], automatic: ImportAutomaticValue[] = [];
    for (const target of targets) {
        const current = valueAt(draft, target.path);
        if (!current) continue;
        if (target.supplied && !emptyValue(current.value) && originOf(origins, target.path) === 'administrator') {
            if (sameLookupValue(target.path, current.value, target.value)) continue;
            const earlier = answered.find(item => item.path === target.path && sameDraftValue(item.lookup, target.value));
            conflicts.push({ path: target.path, lookup: structuredClone(target.value), slotId: target.slotId, answer: earlier?.answer ?? null });
            continue;
        }
        automatic.push({ path: target.path, seen: structuredClone(current.value), value: target.value });
    }
    const result = applyAutomaticValues({ draft, draftOrigins: origins }, automatic);
    // An emptied value is never marked automatic: it is simply empty again.
    for (const path of result.written) if (emptyValue(draftValueAt(draft, path))) delete origins[originKey(path)];
    const flagged: LookupValueFlag[] = [...supplied.flagged];
    for (const skip of result.skipped) {
        if (suppliedPaths.has(skip.path) && (skip.reason === 'size' || skip.reason === 'invalid')) flagged.push({ path: skip.path, reason: skip.reason === 'size' ? 'size' : 'format' });
    }
    const values: LookupAppliedValue[] = [];
    for (const item of supplied.values) {
        const current = valueAt(draft, item.path);
        if (current && originOf(origins, item.path) === 'automatic' && sameDraftValue(current.value, item.value)) values.push({ path: item.path, value: structuredClone(current.value), slotId: item.slotId });
    }
    if (result.written.length) {
        if (Array.isArray(doc.decisions)) doc.decisions = retainBoundDecisions(doc.decisions, draft);
        doc.valueRevision = (Number.isSafeInteger(doc.valueRevision) && doc.valueRevision! >= 0 ? doc.valueRevision! : 0) + 1;
        doc.updatedAt = intent.now;
    }
    return {
        application: { run: intent.run, candidateKey: candidate?.key ?? null, releaseId: candidate?.releaseId ?? null, choice: intent.choice, basis: intent.basis,
            actorId: intent.actorId, operationId: intent.operationId, at: intent.now, paths: result.written, values, conflicts, flagged },
        changed: result.written.length > 0
    };
}

/**
 * Applies a completed run's preselection, as the run's granting administrator in the worker's completion step or as `actorId`
 * (the administrator whose confirmation re-ranked it), unless this run already has an explicit choice or this very preselection,
 * or the candidate is not applicable (not fetched, or fetched under another release ID). A malformed draft applies nothing.
 */
export function applyPreselectedLookup(doc: AdminImportDocument, record: MetadataLookupRecord, now: Date, actorId: string = record.actorId):
    { record: MetadataLookupRecord; changed: boolean } {
    const unchanged = { record, changed: false };
    const preselection = record.state === 'complete' ? record.ranking?.preselection : null;
    if (!preselection || typeof preselection.candidateKey !== 'string') return unchanged;
    const applied = isRecord(record.applied) ? record.applied : null;
    if (applied && applied.run === record.run && (applied.choice !== 'preselected' || applied.candidateKey === preselection.candidateKey)) return unchanged;
    const candidate = Array.isArray(record.candidates) ? record.candidates.find(item => item?.key === preselection.candidateKey) : undefined;
    if (!candidate || !applicable(candidate)) return unchanged;
    try {
        const { application, changed } = applyLookupCandidate(doc, applied, candidate,
            { run: record.run, choice: 'preselected', basis: preselection.basis, actorId, operationId: null, now });
        return { record: { ...record, applied: application }, changed };
    } catch (error) {
        if (error instanceof AdminImportError) return unchanged;
        throw error;
    }
}

/**
 * File evidence a re-rank compares: everything but Disc and Track Numbers, which an application itself writes (in the ranking's
 * file order, so they never change a ranking) and which would otherwise make every later trigger re-rank without new evidence.
 */
const rerankEvidence = (files: unknown) => Array.isArray(files)
    ? files.map(file => isRecord(file) ? Object.fromEntries(Object.entries(file).filter(([name]) => name !== 'discNumber' && name !== 'trackNumber')) : file) : files;
/**
 * Re-ranks a completed run's stored candidates when the import's ranking evidence changed (newly known durations, tags,
 * identifiers or files), then applies a new preselection as `actorId`. The run then binds the file set it re-ranked, so a stale
 * slot whose file was confirmed again is no longer stale (one still without a confirmed file stays stale), while `fileSetDigest`
 * keeps governing automatic reruns. Never makes a request; null when nothing needs re-ranking.
 */
export function rerankStoredLookup(doc: AdminImportDocument, record: MetadataLookupRecord, now: Date, actorId: string = record.actorId):
    { record: MetadataLookupRecord; changed: boolean } | null {
    if (record.state !== 'complete' || record.outcome !== 'candidates' || !isRecord(record.ranking) || !Array.isArray(record.candidates)) return null;
    if (sameDraftValue(rerankEvidence(lookupFileEvidence(doc)), rerankEvidence(record.ranking.files))) return null;
    const ranked = rankLookupWithinBudget(record.candidates, doc, now), files = importLookupFileSet(doc).files;
    const confirmed = new Set(files.filter(file => file.operationId !== null && file.sha256 !== null).map(file => file.slotId));
    const staleSlotIds = (Array.isArray(record.staleSlotIds) ? record.staleSlotIds : []).filter(slot => !confirmed.has(slot));
    return applyPreselectedLookup(doc, { ...record, files, staleSlotIds, candidates: ranked.candidates, ranking: ranked.ranking, updatedAt: now }, now, actorId);
}

/**
 * What publication waits for besides an active run: a tie (a completed run with two or more matching groups, no preselection and
 * no explicit choice for that run) and the unanswered conflicts whose current value still differs from the lookup value. An
 * append ignores Album conflicts. Malformed stored items are ignored and never block.
 */
export function lookupAnswersNeeded(record: Partial<MetadataLookupRecord> | null | undefined, doc: AdminImportDocument, options: { append: boolean }):
    { tie: boolean; conflicts: ImportDraftPath[] } {
    if (!isRecord(record)) return { tie: false, conflicts: [] };
    const applied = isRecord(record.applied) ? record.applied : null;
    const chosen = applied?.run === record.run && (applied?.choice === 'chosen' || applied?.choice === 'none');
    const ranking = isRecord(record.ranking) ? record.ranking : null;
    const tie = record.state === 'complete' && Array.isArray(ranking?.groups) && ranking!.groups.length >= 2 && !ranking!.preselection && !chosen;
    let draft: ImportDraftV2 | null; try { draft = storedDraftV2(doc); } catch { draft = null; }
    const conflicts = draft ? storedConflicts(applied).filter(item => item.answer === null && !(options.append && item.path.startsWith('album.'))
        && (() => { const current = valueAt(draft!, item.path); return current !== null && !sameLookupValue(item.path, current.value, item.lookup); })()).map(item => item.path) : [];
    return { tie, conflicts: [...new Set(conflicts)] };
}

/**
 * An administrator's choice of a candidate of the current run (complete, with fetched details) or of none (any finished run),
 * applied at once; the run's grant moves to that administrator (`choose`). Refused as stale for another run, an active run or
 * an unknown candidate, and as incomplete for a candidate without fetched details or whose fetched release has another ID.
 */
export function chooseLookupCandidate(doc: AdminImportDocument, record: MetadataLookupRecord | null,
    request: { run: number; candidateKey: string | null; actorId: string; operationId: string }, now: Date): MetadataLookupRecord {
    if (!record || record.run !== request.run || isBlockingLookupState(record.state)) throw stale();
    let candidate: StoredLookupCandidate | null = null;
    if (request.candidateKey !== null) {
        if (record.state !== 'complete' || !Array.isArray(record.candidates)) throw stale();
        candidate = record.candidates.find(item => item?.key === request.candidateKey) ?? null;
        if (!candidate) throw stale();
        if (!applicable(candidate)) throw new AdminImportError(409, 'ADMIN_IMPORT_LOOKUP_CANDIDATE_INCOMPLETE');
    }
    const { application } = applyLookupCandidate(doc, isRecord(record.applied) ? record.applied : null, candidate, {
        run: record.run, choice: candidate ? 'chosen' : 'none', basis: candidate ? 'chosen' : null, actorId: request.actorId, operationId: request.operationId, now
    });
    return refreshLookupGrant({ ...record, applied: application }, request.actorId, 'choose', now);
}

/**
 * Answers conflicts of the applied candidate: `lookup` writes the lookup value as the administrator's own, `mine` keeps the
 * current value. Each answer binds the application (run and candidate) and its path's current value (`base`), so a stale
 * application is ADMIN_IMPORT_LOOKUP_STALE and a changed value ADMIN_IMPORT_FIELD_CONFLICT, writing nothing.
 */
export function resolveLookupConflicts(doc: AdminImportDocument, record: MetadataLookupRecord | null,
    request: { run: number; candidateKey: string | null; answers: readonly { path: ImportDraftPath; answer: 'mine' | 'lookup'; base: unknown }[] }, now: Date): MetadataLookupRecord {
    const applied = record && isRecord(record.applied) ? record.applied : null;
    if (!record || !applied || request.candidateKey === null || applied.run !== request.run || applied.candidateKey !== request.candidateKey) throw stale();
    const draft = storedDraftV2(doc), before = structuredClone(draft), origins = doc.draftOrigins ??= {};
    const conflicts = storedConflicts(applied).map(item => ({ ...item }));
    let values = storedValues(applied);
    for (const { path, answer, base } of request.answers) {
        const conflict = conflicts.find(item => item.path === path);
        if (!conflict) throw stale();
        if (!sameDraftValue(draftValueAt(draft, path), base)) throw new AdminImportError(409, 'ADMIN_IMPORT_FIELD_CONFLICT');
        if (answer === 'lookup') {
            let value: unknown; try { value = parseDraftValue(path, conflict.lookup, draft); } catch { throw stale(); }
            setDraftValue(draft, path, value);
            markAdministratorValues(origins, [path]);
            values = [...values.filter(item => item.path !== path), { path, value: structuredClone(value), slotId: conflict.slotId ?? null }];
        }
        conflict.answer = answer;
    }
    if (!draftWithinSizeLimit(before, draft)) invalidImport();
    if (Array.isArray(doc.decisions)) doc.decisions = retainBoundDecisions(doc.decisions, draft);
    return { ...record, applied: { ...applied, conflicts, values }, updatedAt: now };
}
